package tokenizer

import (
	"fmt"
	"math"
	"sync"
	"unicode"
)

// Anthropic has never published the vocabulary its current models use, and the
// count_tokens endpoint is the only authority on it. This file holds an offline
// estimator for those counts: a BPE tokenizer this repository does embed runs
// over the text, and a per-character-class correction, fitted against measured
// counts, maps its output onto what Anthropic reports. Nothing here reaches the
// network.
//
// Measurement found two live tokenizers, not one. They agree exactly on digits,
// punctuation, and every non-Latin script, and disagree on runs of ASCII
// letters, where the newer one is markedly more granular. AnthropicFamily names
// that split; EncodingForModel maps a model id onto it.

// AnthropicFamily identifies a tokenizer shared by a group of Claude models.
type AnthropicFamily string

const (
	// FamilyClaude45 covers the Claude 4.5 and 4.6 generation.
	FamilyClaude45 AnthropicFamily = "claude_4_5"
	// FamilyClaude5 covers the Claude 5 generation, including Opus 4.8.
	FamilyClaude5 AnthropicFamily = "claude_5"
)

// anthropicClass buckets a pre-token by script and case. The correction is
// fitted per class because the error of the embedded BPE against Anthropic's
// tokenizer is script-dependent: it tracks Latin text far better than it tracks
// Han or Cyrillic, and the two families differ only on ASCII letters.
type anthropicClass int

const (
	classWordLower anthropicClass = iota
	classWordCapital
	classWordUpper
	classWordLatin
	classWordCyrillic
	classWordCJK
	classWordHangul
	classWordOtherScript
	classNumber
	classPunct
	classSymbol
	classSpaceRun
	classNewlineRun
	classRepeatRun
	numAnthropicClasses
)

// repeatRunThreshold is the length past which a pre-token of one repeated
// character is charged from its length alone.
//
// The base encoding's cost for such a run says almost nothing about
// Anthropic's, because each vocabulary holds its own long single-character
// tokens: measured at four hundred characters, a run of "a" costs 2.7x what the
// base encoding spends while a run of "x" costs 1.04x. Reading the base cost
// there is worse than ignoring it, so these runs are priced by length in their
// own class. Which specific runs are cheap stays unknowable from outside, and
// docs/anthropic-estimator.md records the error that leaves.
const repeatRunThreshold = 4

// anthropicFeatures is what the correction is a linear function of: for every
// class, how many tokens the embedded BPE spent, how many pre-tokens fell in
// it, and how many runes those held.
type anthropicFeatures struct {
	BaseTokens [numAnthropicClasses]float64
	Pr

eTokens  [numAnthropicClasses]float64
	Runes      [numAnthropicClasses]float64
	LongRunes  [numAnthropicClasses]float64
	HugeRunes  [numAnthropicClasses]float64
}

// A pre-token's length is split at these breakpoints so each span gets its own
// rate. A long run of one character is where the embedded BPE and Anthropic's
// tokenizer diverge hardest: the embedded one holds tokens covering such a run
// and spends few, Anthropic's spends many. One rate per rune cannot fit a short
// word, an indent, and a four-hundred-character run at once.
const (
	longRuneThreshold = 8
	hugeRuneThreshold = 64
)

// anthropicWeights is the fitted correction for one family.
type anthropicWeights struct {
	Base     [numAnthropicClasses]float64
	Pre      [numAnthropicClasses]float64
	Rune     [numAnthropicClasses]float64
	LongRune [numAnthropicClasses]float64
	HugeRune [numAnthropicClasses]float64
	Offset   float64
}

// predict applies the correction to extracted features.
func (w *anthropicWeights) predict(f *anthropicFeatures) float64 {
	total := w.Offset
	for c := anthropicClass(0); c < numAnthropicClasses; c++ {
		total += w.Base[c]*f.BaseTokens[c] + w.Pre[c]*f.PreTokens[c] +
			w.Rune[c]*f.Runes[c] + w.LongRune[c]*f.LongRunes[c] + w.HugeRune[c]*f.HugeRunes[c]
	}
	return total
}

// classifyPreToken buckets a pre-token by its letters, falling back to its
// symbols when it holds none. A pre-token produced by the cl100k pattern is
// homogeneous enough that its first letter decides the script.
// isRepeatRun reports whether s is one non-whitespace character repeated at

// least repeatRunThreshold times.
func isRepeatRun(s string) bool {
	var first rune = -1
	n := 0
	for _, r := range s {
		if unicode.IsSpace(r) {
			return false
		}
		if first < 0 {
			first = r
		} else if r != first {
			return false
		}
		n++
	}
	return n >= repeatRunThreshold
}

func classifyPreToken(s string) anthropicClass {
	if isRepeatRun(s) {
		return classRepeatRun
	}
	var (
		letters, upper, lower, digits, space, newline, nonASCII int
		firstLetter                                             rune = -1
	)
	for _, r := range s {
		switch {
		case unicode.IsLetter(r):
			letters++
			if firstLetter < 0 {
				firstLetter = r
			}
			if unicode.IsUpper(r) {
				upper++
			} else if unicode.IsLower(r) {
				lower++
			}
		case unicode.IsDigit(r):
			digits++
		case r == '\n' || r == '\r':
			newline++
		case unicode.IsSpace(r):
			space++
		}
		if r > unicode.MaxASCII {
			nonASCII++
		}
	}

	if letters == 0 {
		switch {
		case digits > 0:
			return classNumber
		// A run holding a line break is charged differently from a run of
		// spaces or tabs, so the two do not share a rate.
		case newline > 0:
			return classNewlineRun
		case space > 0:
			return classSpaceRun
		case nonASCII > 0:
			return classSymbol
		default:
			return classPunct
		}
	}

	switch {
	case unicode.Is(unicode.Han, firstLetter),
		unicode.Is(unicode.Hiragana, firstLetter),
		unicode.Is(unicode.Katakana, firstLetter):
		return classWordCJK
	case unicode.Is(unicode.Hangul, firstLetter):
		return classWordHangul
	case unicode.Is(unicode.Cyrillic, firstLetter), unicode.Is(unicode.Greek, firstLetter):
		return classWordCyrillic
	case !unicode.Is(unicode.Latin, firstLetter):
		return classWordOtherScript
	case nonASCII > 0:
		return classWordLatin
	case upper >= 2 && lower == 0:
		return classWordUpper
	case upper > 0 && unicode.IsUpper(firstLetter):
		return classWordCapital
	default:
		return classWordLower
	}
}

// AnthropicEstimator reports how many tokens Anthropic's tokenizer would spend
// on a text. It answers offline, from an embedded vocabulary and a fitted
// correction, and never contacts the API.
//
// It estimates a count and does not reproduce a segmentation: Anthropic
// publishes no vocabulary for these models, so there are no token IDs to
// return. Encode and Decode say so rather than inventing IDs.
type AnthropicEstimator struct {
	weights anthropicWeights
	family  AnthropicFamily
}

// The base tokenizer is shared: every family corrects the output of the same
// embedded encoding, and loading that vocabulary is the expensive part.
var (
	anthropicBaseOnce sync.Once
	anthropicBase     *tokenizer
	anthropicBaseErr  error
)

func loadAnthropicBase() (*tokenizer, error) {
	anthropicBaseOnce.Do(func() {
		tok, err := NewWithEncoding(anthropicBaseEncoding)
		if err != nil {
			anthropicBaseErr = fmt.Errorf("loading base encoding %s: %w", anthropicBaseEncoding, err)
			return
		}
		anthropicBase = tok.(*tokenizer)
	})
	return anthropicBase, anthropicBaseErr
}

// NewAnthropicEstimator builds an

 estimator for one tokenizer family.
func NewAnthropicEstimator(family AnthropicFamily) (*AnthropicEstimator, error) {
	weights, ok := anthropicWeightsByFamily[family]
	if !ok {
		return nil, fmt.Errorf("no fitted weights for Anthropic family %q", family)
	}
	if _, err := loadAnthropicBase(); err != nil {
		return nil, err
	}
	return &AnthropicEstimator{weights: weights, family: family}, nil
}

// extractAnthropicFeatures runs the base tokenizer and buckets its output.
func extractAnthropicFeatures(text string) (*anthropicFeatures, error) {
	base, err := loadAnthropicBase()
	if err != nil {
		return nil, err
	}
	preTokens, err := base.preTokenizer.Tokenize(text)
	if err != nil {
		return nil, fmt.Errorf("pre-tokenization failed: %w", err)
	}

	f := &anthropicFeatures{}
	for _, pt := range preTokens {
		class := classifyPreToken(pt.Text)
		runes := len([]rune(pt.Text))
		f.BaseTokens[class] += float64(base.bpe.CountTokens([]byte(pt.Text)))
		f.PreTokens[class]++
		f.Runes[class] += float64(runes)
		if runes > longRuneThreshold {
			f.LongRunes[class] += float64(runes - longRuneThreshold)
		}
		if runes > hugeRuneThreshold {
			f.HugeRunes[class] += float64(runes - hugeRuneThreshold)
		}
	}
	return f, nil
}

// The shape of the vector AnthropicFeatureVector returns, published so a
// calibration tool can build a design matrix without depending on internals.
// The vector holds each aggregate over every class in turn, then a constant.
const (
	AnthropicFeatureClasses    = int(numAnthropicClasses)
	AnthropicFeatureAggregates = 5
)

// AnthropicASCIILetterClasses lists the class indices where the two families
// were measured to disagree. A joint fit shares every other weight between
// them, which is what lets the family with fewer measurements borrow the
// other's evidence for scripts they charge identically for.
func AnthropicASCIILetterClasses() []int {
	return []int{int(classWordLower), int(classWordCapital), int(classWordUpper)}
}

// AnthropicFeatureVector exposes the features the fitted correction is a linear
// function of, flattened in the order the weights are stored and ending in the
// constant term. A calibration tool fits weights against measured counts with
// it; the shipped estimator needs no such call.
func AnthropicFeatureVector(text string) ([]float64, error) {
	f, err := extractAnthropicFeatures(text)
	if err != nil {
		return nil, err
	}
	v := make([]float64, 0, AnthropicFeatureAggregates*AnthropicFeatureClasses+1)
	v = append(v, f.BaseTokens[:]...)
	v = append(v, f.PreTokens[:]...)
	v = append(v, f.Runes[:]...)
	v = append(v, f.LongRunes[:]...)
	v = append(v, f.HugeRunes[:]...)
	return append(v, 1), nil
}

// CountTokens estimates the tokens Anthropic's tokenizer spends on text.
func (e *AnthropicEstimator) CountTokens(text string) (int, error) {
	if text == "" {
		return 0, nil
	}
	f, err := extract

AnthropicFeatures(text)
	if err != nil {
		return 0, err
	}
	n := int(math.Round(e.weights.predict(f)))
	if n < 1 {
		// Any non-empty text costs at least a token; a correction that
		// undershoots into zero or below would be reported as free.
		n = 1
	}
	return n, nil
}

// Encode reports that no segmentation is available. Returning invented IDs
// would let a caller decode them back into text that was never tokenized.
func (e *AnthropicEstimator) Encode(string) ([]int, error) {
	return nil, fmt.Errorf("encoding %s: Anthropic publishes no vocabulary for these models, so token IDs cannot be produced; use CountTokens", e.family)
}

// Decode reports the same absence as Encode.
func (e *AnthropicEstimator) Decode([]int) (string, error) {
	return "", fmt.Errorf("encoding %s: Anthropic publishes no vocabulary for these models, so token IDs cannot be decoded", e.family)
}

// VocabSize reports the size of the vocabulary actually consulted, which is the
// base encoding's rather than Anthropic's unpublished one.
func (e *AnthropicEstimator) VocabSize() int {
	base, err := loadAnthropicBase()
	if err != nil {
		return 0
	}
	return base.VocabSize()
}

// MessageOverhead is the token cost the Messages API adds around a single
// user text message, measured per family. Add it to a CountTokens result to
// predict what count_tokens reports for that message.
func (e *AnthropicEstimator) MessageOverhead() int { return anthropicOverheadByFamily[e.family] }

// EncodingForModel maps a Claude model id onto the encoding name that estimates
// its token counts. It reports false for an id whose family has not been
// measured, so a caller cannot silently budget with the wrong tokenizer.
func EncodingForModel(model string) (string, bool) {
	family, ok := anthropicFamilyByModel[model]
	if !ok {
		return "", false
	}
	return string(family), true
}

package tokenizer

import (
	"bufio"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"sort"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/wow-look-at-my/go-containers/set"
)

// countCase is one row of testdata/anthropic-counts.jsonl: a text and what the
// token counting API reported for it, per family. The counts are measurements,
// not expectations produced by this package, so a change that drifts away from
// Anthropic's tokenizer fails here.
type countCase struct {
	ID        string         `json:"id"`
	Category  string         `json:"category"`
	Text      string         `json:"text"`
	APICounts map[string]int `json:"apiCounts"`
}

// adversarialCategories hold shapes built to break the estimator rather than to
// represent real input. Their cost turns on which long single-character tokens
// each vocabulary happens to contain, which Anthropic does not publish, so they
// carry their own looser bound. docs/anthropic-estimator.md explains why.
var adversarialCategories = set.Of[string]("repetition", "whitespace")

func loadCountCases(t *testing.T) []countCase {
	t.Helper()

	f, err := os.Open("testdata/anthropic-counts.jsonl")
	require.NoError(t, err)
	defer f.Close()

	var cases []countCase
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 0, 1<<20), 1<<20)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		var c countCase
		require.NoError(t, json.Unmarshal([]byte(line), &c))
		cases = append(cases, c)
	}
	require.NoError(t, scanner.Err())
	require.NotEmpty(t, cases)
	return cases
}

// errorPercentiles reports the mean and the given percentile of a sorted error
// sample, so a bound can be stated on the shape of the distribution rather than
// on a single worst case.
func errorPercentiles(errs []float64, p float64) (mean, pct float64) {
	sort.Float64s(errs)
	sum := 0.0
	for _, e := range errs {
		sum += e
	}
	return sum / float64(len(errs)), errs[int(float64(len(errs)-1)*p)]
}

// TestAnthropicEstimatorAccuracy holds the

 estimator to the accuracy it was
// measured at. The bounds sit a little above the fit so ordinary noise does not
// fail the build, and far enough below the uncorrected base encoding that a
// regression to it cannot pass.
func TestAnthropicEstimatorAccuracy(t *testing.T) {
	cases := loadCountCases(t)

	for _, family := range []AnthropicFamily{FamilyClaude45, FamilyClaude5} {
		t.Run(string(family), func(t *testing.T) {
			est, err := NewAnthropicEstimator(family)
			require.NoError(t, err)

			var ordinary, adversarial []float64
			for _, c := range cases {
				want, ok := c.APICounts[string(family)]
				if !ok {
					continue
				}
				got, err := est.CountTokens(c.Text)
				require.NoError(t, err, c.ID)

				// The fixture stores what the API reports for a whole message,
				// so the per-message overhead comes off before comparing.
				errPct := math.Abs(float64(got+est.MessageOverhead()-want)) / float64(want) * 100
				if adv

ersarialCategories.Contains(c.Category) {
					adversarial = append(adversarial, errPct)
				} else {
					ordinary = append(ordinary, errPct)
				}
			}
			require.NotEmpty(t, ordinary)

			mean, p90 := errorPercentiles(ordinary, 0.9)
			t.Logf("representative text: n=%d mean %.2f%% p90 %.2f%%", len(ordinary), mean, p90)
			assert.Less(t, mean, 8.0, "mean error on representative text regressed")
			assert.Less(t, p90, 16.0, "90th percentile error on representative text regressed")

			if len(adversarial) > 0 {
				advMean, advP90 := errorPercentiles(adversarial, 0.9)
				t.Logf("adversarial runs: n=%d mean %.2f%% p90 %.2f%%", len(adversarial), advMean, advP90)
				assert.Less(t, advMean, 90.0, "error on single-character runs regressed")
			}
		})
	}
}

// TestAnthropicEstimatorBeatsBaseEncoding proves the correction is doing the
// work. Without it the base encoding is wrong by tens of percent, and a fit
// that silently degenerated to passing its output through would fail here.
func TestAnthropicEstimatorBeatsBaseEncoding(t *testing.T) {
	cases := loadCountCases(t)
	base, err := NewWithEncoding(anthropicBaseEncoding)
	require.NoError(t, err)

	for _, family := range []AnthropicFamily{FamilyClaude45, FamilyClaude5} {
		t.Run(string(family), func(t *testing.T) {
			est, err := NewAnthropicEstimator(family)
			require.NoError(t, err)

			var estErrs, baseErrs []float64
			for _, c := range cases {
				want, ok := c.APICounts[string(family)]
				if !ok || adversarialCategories.Contains(c.Category) {
					continue
				}
				got, err := est.CountTokens(c.Text)
				require.NoError(t, err)
				raw,

err := base.CountTokens(c.Text)
				require.NoError(t, err)

				estErrs = append(estErrs, math.Abs(float64(got+est.MessageOverhead()-want))/float64(want)*100)
				baseErrs = append(baseErrs, math.Abs(float64(raw-want))/float64(want)*100)
			}

			estMean, _ := errorPercentiles(estErrs, 0.9)
			baseMean, _ := errorPercentiles(baseErrs, 0.9)
			t.Logf("estimator %.2f%% vs base encoding %.2f%%", estMean, baseMean)
			assert.Less(t, estMean*2, baseMean, "the correction should at least halve the base encoding's error")
		})
	}
}

// TestAnthropicFamiliesDisagreeOnASCII records the measurement that motivates
// separate flavors: the two tokenizers charge differently for ASCII letters.
// One flavor for both would be wrong for whichever it was not fitted to.
func TestAnthropicFamiliesDisagreeOnASCII(t *testing.T) {
	older, err := NewAnthropicEstimator(FamilyClaude45)
	require.NoError(t, err)
	newer, err := NewAnthropicEstimator(FamilyClaude5)
	require.NoError(t, err)

	const pangram = "The quick brown fox jumps over the lazy dog. "
	oldCount, err := older.CountTokens(strings.Repeat(pangram, 8))
	require.

NoError(t, err)
	newCount, err := newer.CountTokens(strings.Repeat(pangram, 8))
	require.NoError(t, err)

	assert.Greater(t, newCount, oldCount, "the newer tokenizer was measured as the more granular one on ASCII text")
}

// TestAnthropicEstimatorRefusesToEncode guards the honesty of the API surface:
// Anthropic publishes no vocabulary for these models, so there are no token IDs
// to hand back, and inventing them would let a caller decode nonsense.
func TestAnthropicEstimatorRefusesToEncode(t *testing.T) {
	est, err := NewAnthropicEstimator(FamilyClaude5)
	require.NoError(t, err)

	_, err = est.Encode("hello")
	require.Error(t, err)
	assert.Contains(t, err.Error(), "CountTokens")

	_, err = est.Decode([]int{1, 2, 3})
	require.Error(t, err)
}

// TestEncodingForModel maps model ids onto flavors, and reports rather than
// guesses when an id has not been measured.
func TestEncodingForModel(t *testing.T) {
	for model, want := range map[string]string{
		"claude-opus-5":              string(FamilyClaude5),
		"claude-sonnet-5":            string(FamilyClaude5),
		"claude-opus-4-8":            string(FamilyClaude5),
		"claude-sonnet-4-6":          string(FamilyClaude45),
		"claude-opus-4-5-20251101":   string(FamilyClaude45),
		"claude-haiku-4-5-20251001":  string(FamilyClaude45),
		"claude-sonnet-4-5-20250929": string(FamilyClaude45),
	} {
		got, ok := EncodingForModel(model)
		require.True(t, ok, model)
		assert.Equal(t, want, got, model)
	}

	_, ok := EncodingForModel("gpt-4o")
	assert.False(t, ok, "an unmeasured model must not be given a flavor by guesswork")
}

// TestAnthropicEstimatorViaEncoding checks the flavors are reachable by name,
// which is how the CLI and library callers select them.
func TestAnthropicEstimatorViaEncoding(t *testing.T) {
	for _, name := range []string{string(FamilyClaude45), string(FamilyClaude5)} {
		tok, err := NewWithEncoding(name)
		require.NoError(t, err, name)

		n, err := tok.CountTokens("The quick brown fox jumps over the lazy dog.")
		require.NoError(t, err)
		assert.Positive(t, n)
	}
}

// TestClassifyPreToken pins the bucketing the correction is fitted per, so a
// later edit cannot quietly reroute a script into another class and invalidate
// every weight.
func TestClassifyPreToken(t *testing.T) {
	for text, want := range map[string]anthropicClass{
		" the":     classWordLower,
		" The":     classWordCapital,
		" HTTP":    classWordUpper,
		" café":    classWordLatin,
		" Привет":  classWordCyrillic,
		"日本":       classWordCJK,
		"

한국어":     classWordHangul,
		" مرحبا":   classWordOtherScript,
		" 1234":    classNumber,
		"();":      classPunct,
		"    ":     classSpaceRun,
		"\n\n":     classNewlineRun,
		"aaaaaaaa": classRepeatRun,
		"--------": classRepeatRun,
	} {
		assert.Equal(t, want, classifyPreToken(text), fmt.Sprintf("%q", text))
	}
}

package tokenizer

// Fitted data for the Anthropic estimator. Regenerate it with
// `cmd/anthropic-calibrate`, which measures counts against the token counting
// API and refits; see docs/anthropic-estimator.md for the procedure and the
// error the current fit achieves.

// anthropicBaseEncoding is the embedded encoding whose output the correction
// adjusts. It is not Anthropic's tokenizer and is not claimed to be: it is a
// well-behaved BPE over the same text, and the correction carries the rest.
const anthropicBaseEncoding = "cl100k_base"

// anthropicFamilyByModel maps a measured model id onto its tokenizer family.
var anthropicFamilyByModel = map[string]AnthropicFamily{
	"claude-opus-4-5":            FamilyClaude45,
	"claude-opus-4-5-20251101":   FamilyClaude45,
	"claude-sonnet-4-5":          FamilyClaude45,
	"claude-sonnet-4-5-20250929": FamilyClaude45,
	"claude-haiku-4-5":           FamilyClaude45,
	"claude-haiku-4-5-20251001":  FamilyClaude45,
	"claude-sonnet-4-6":          FamilyClaude45,
	"claude-opus-4-6":            FamilyClaude45,
	"claude-opus-4-7":            FamilyClaude5,
	"claude-opus-4-8":            FamilyClaude5,
	"claude-opus-5":              FamilyClaude5,
	"claude-sonnet-5":            FamilyClaude5,
	"claude-fable-5":             FamilyClaude5,
	"claude-fable-5-1":           FamilyClaude5,
}

// anthropicOverheadByFamily is the measured token cost the Messages API adds
// around a single user text message.
var anthropicOverheadByFamily = map[AnthropicFamily]int{
	FamilyClaude45: 7,
	FamilyClaude5:  6,
}

// anthropicWeightsByFamily holds the fitted correction per family.
//
// The two families were fitted together against one design matrix. Every class
// outside runs of ASCII letters shares a single set of weights, because measured
// counts are identical there; only the ASCII-letter classes carry a per-family
// difference. That sharing is why the family with far fewer measurements still
// prices Han, Cyrillic, digits, and punctuation as accurately as the other.
var anthropicWeightsByFamily = map[AnthropicFamily]anthropicWeights{
	FamilyClaude45: {
		Base:     [numAnthrop

package tokenizer

import (
	"fmt"
	"github.com/stretchr/testify/require"
	"strings"
	"testing"
)

// ---------------------------------------------------------------------------
// Test‑data helpers
// ---------------------------------------------------------------------------

// englishProse returns roughly n bytes of English prose.
func englishProse(n int) string {
	const sentence = "The quick brown fox jumps over the lazy dog. "
	reps := (n / len(sentence)) + 1
	return strings.Repeat(sentence, reps)[:n]
}

// codeSnippet returns roughly n bytes of Go source code.
func codeSnippet(n int) string {
	const block = `func main() {
	for i := 0; i < 100; i++ {
		fmt.Printf("iteration %d: value=%v\n", i, compute(i))
	}
}
`
	reps := (n / len(block)) + 1
	return strings.Repeat(block, reps)[:n]
}

// unicodeText returns roughly n bytes of CJK‑heavy Unicode text.
func unicodeText(n int) string {
	const block = "日本語のテスト文章です。中文测试文本。한국어 테스트 문장입니다. "
	reps := (n / len(block)) + 1
	s := strings.Repeat(block, reps)
	// Truncate at rune boundary
	r := []rune(s)
	for i := len(r); i > 0; i-- {
		if len(string(r[:i])) <= n {
			return string(r[:i])
		}
	}
	return ""
}

// numberText returns roughly n bytes of numeric/mixed‑digit text.
func numberText(n int) string {
	const block = "There are 12345 items costing $67.89 each, totaling 838,102.05 units. "
	reps := (n / len(block)) + 1
	return strings.Repeat(block, reps)[:n]
}

// specialTokenText returns text interspersed with special tokens.
func specialTokenText(n int) string {
	const block = "Hello world<|endoftext|>Another segment<|fim_prefix|>code here<|fim_suffix|>more text. "
	reps := (n / len(block)) + 1
	return strings.Repeat(block, reps)[:n]
}

// whitespaceHeavy returns text with lots of whitespace and newlines.
func whitespaceHeavy(n int) string {
	const block = "word   another\t\ttabbed\n\nnewlines\n   indented   trailing   \n"
	reps := (n / len(block)) + 1
	return strings.Repeat(block, reps)[:n]
}

